964	/// Why the structural lane leaves an application of `Partial`, `Required`, `Pick` or `Omit` as written: a fact the
965	/// expansion would read is not recorded, or not complete. The checker lane (ADR 0026) answers it instead.
966	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
967	pub(super) enum Declined {
968	    /// The name is bound to a declaration of the project (in its file, or a scope enclosing the reference), not to
969	    /// TypeScript's lib type.
970	    NotLibUtility,
971	    /// The object it maps is not one whose members are recorded one by one: a type parameter, a conditional, a type
972	    /// from a file the run does not read.
973	    UnknownObject,
974	    /// The object declares a member the collected model does not list: an index signature, a member whose key is not
975	    /// a static name, or it is a class.
976	    UnlistedMembers,
977	    /// A generic interface, or one extending a type that is not such an interface: its members are not all recorded.
978	    UnknownParent,
979	    /// A member an interface and one it extends (or two of its parents) both declare: where the checker lists it is not
980	    /// recorded.
981	    Redeclared,
982	    /// The interface a name finds is declared in a scope that does not enclose the reference.
983	    OutOfScope,
984	    /// The keys of `Pick` or `Omit` are not a known set of names.
985	    UnknownKeys,
986	    /// `Pick` lists its keys in an order other than the object's members: the checker's order is not recorded.
987	    KeyOrder,
988	    /// `Pick` names a key the object does not have, an error TypeScript reports.
989	    MissingKey,
990	    /// `Required` over an optional member whose type may hold `undefined` through a name.
991	    OptionalUndefined,
992	    /// Nested past `MAX_DEPTH`.
993	    TooDeep,
994	}
