1005	/// The members TypeScript's `Partial`, `Required`, `Pick` or `Omit` (named `name`, written in `file` within `scope`)
1006	/// gives `args`. Structural expansion is exact or declined: it proceeds only when every fact it reads is recorded and
1007	/// complete, which is when the name is TypeScript's own (bound to nothing in `file` or an enclosing scope); the object
1008	/// it maps is an object literal, an interface without type parameters (its own members, then its parents'), an alias of
1009	/// one, or another of these four over one, found from `scope` and listing every member it declares (no index
1010	/// signature, no computed key); `Pick` and `Omit` have their keys as literals, an alias of them or `keyof` of such an
1011	/// object; and `Required` drops `undefined` only from a type that holds it by no name. `Omit<A[], keyof B[]>`, both
1012	/// TypeScript's `Array`, takes every key an array has away and leaves `{}`. Modifiers are kept: `readonly` as declared,
1013	/// and `?` as each utility sets it. Anything else is [`Declined`], and the application stays.
1014	pub(super) fn structural_expansion(
1015	    name: &str,
1016	    args: &[CollectedType],
1017	    file: &Utf8Path,
1018	    scope: &DeclarationScope,
1019	    ctx: &ResolutionContext,
1020	    depth: u8,
1021	) -> Exactness {
1022	    if depth > MAX_DEPTH {
1023	        return Err(Declined::TooDeep);
1024	    }
1025	    if !is_structural_utility(name) || !is_lib_type(name, file, scope, ctx) {
1026	        return Err(Declined::NotLibUtility);
1027	    }
1028	    match (name, args) {
1029	        ("Partial" | "Required", [base]) => {
1030	            let required = name == "Required";
1031	            let mut fields = object_fields(base, file, scope, ctx, depth + 1)?;
1032	            for located in &mut fields {
1033	                let ty = &mut located.field.collected_type;
1034	                if required && !located.field.required {
1035	                    // `-?` takes `undefined` out of an optional member's type, as `Required` declares.
1036	                    *ty = without_undefined(ty)?;
1037	                }
1038	                located.field.required = required;
1039	            }
1040	            Ok(fields)
1041	        }
1042	        ("Omit", [base, CollectedType::KeyOf(keys)])
1043	            if is_lib_array(base, file, scope, ctx) && is_lib_array(keys, file, scope, ctx) =>
1044	        {
1045	            Ok(Vec::new())
1046	        }
1047	        ("Pick" | "Omit", [base, keys]) => {
1048	            // The keys are read from the same scope and with the same fidelity as the object.
1049	            let mut keys = key_names(keys, file, scope, ctx, depth + 1)?;
1050	            // A key union holds each name once (`Keys | "a"` over a `Keys` that has `"a"`).
1051	            let mut seen = std::collections::HashSet::new();
1052	            keys.retain(|key| seen.insert(key.clone()));
1053	            let mut fields = object_fields(base, file, scope, ctx, depth + 1)?;
1054	            // The checker lists a mapped type's members in the order of its key union, which it sorts by when each
1055	            // literal type was first created anywhere in the program: not recorded. Keys in the object's own member
1056	            // order give that order either way; any other order is declined.
1057	            let in_member_order = fields
1058	                .iter()
1059	                .filter(|f| keys.contains(&f.field.name))
1060	                .map(|f| &f.field.name)
1061	                .eq(keys.iter().filter(|key| fields.iter().any(|f| &f.field.name == *key)));
1062	            if name == "Pick" && !in_member_order {
1063	                return Err(Declined::KeyOrder);
1064	            }
1065	            if name == "Pick" {
1066	                // `[P in K]` lists the members in the keys' order. A key the object lacks is an error TypeScript
1067	                // reports; nothing is guessed for it.
1068	                return keys
1069	                    .iter()
1070	                    .map(|key| fields.iter().find(|f| &f.field.name == key).cloned().ok_or(Declined::MissingKey))
1071	                    .collect();
1072	            }
1073	            fields.retain(|f| !keys.contains(&f.field.name));
1074	            Ok(fields)
1075	        }
1076	        _ => Err(Declined::UnknownObject),
1077	    }
1078	}
