1087	/// The members of `ty`, written in `file` within `scope`, read as `structural_expansion` describes.
1088	fn object_fields(
1089	    ty: &CollectedType,
1090	    file: &Utf8Path,
1091	    scope: &DeclarationScope,
1092	    ctx: &ResolutionContext,
1093	    depth: u8,
1094	) -> Exactness {
1095	    if depth > MAX_DEPTH {
