1269	/// Whether `ty` is an array type `T[]` or TypeScript's `Array<T>` (bound to nothing where it is written), whose keys
1270	/// are the same whatever `T` is.
1271	fn is_lib_array(ty: &CollectedType, file: &Utf8Path, scope: &DeclarationScope, ctx: &ResolutionContext) -> bool {
1272	    match ty {
1273	        CollectedType::AtFile { file: at, inner } if at != file => {
1274	            is_lib_array(inner, at, &DeclarationScope::default(), ctx)
1275	        }
1276	        CollectedType::AtFile { inner, .. } => is_lib_array(inner, file, scope, ctx),
1277	        CollectedType::Array(_) => true,
1278	        CollectedType::Named { name, args } => {
1279	            name == "Array" && args.len() == 1 && is_lib_type(name, file, scope, ctx)
