1285	/// `ty` without `undefined`, as `-?` leaves an optional member's type: `undefined` alone leaves `never`. Declined when
1286	/// a member may hold `undefined` through a name (an alias, a type parameter) or a form not read here.
1287	fn without_undefined(ty: &CollectedType) -> Result<CollectedType, Declined> {
1288	    let members = match ty {
1289	        CollectedType::Union(members) => members.as_slice(),
1290	        single => std::slice::from_ref(single),
1291	    };
1292	    let mut kept = Vec::with_capacity(members.len());
1293	    for member in members {
1294	        match member {
1295	            CollectedType::Undefined => {}
1296	            member if holds_no_undefined(member) => kept.push(member.clone()),
1297	            _ => return Err(Declined::OptionalUndefined),
1298	        }
1299	    }
1300	    Ok(match kept.len() {
1301	        0 => CollectedType::Never,
1302	        1 => kept.into_iter().next().unwrap_or(CollectedType::Never),
1303	        _ => CollectedType::Union(kept),
1304	    })
1305	}
