1307	/// Whether `ty` surely holds no `undefined`, or is `any` or `unknown`, which `-?` leaves as they are.
1308	fn holds_no_undefined(ty: &CollectedType) -> bool {
1309	    match ty {
1310	        CollectedType::AtFile { inner, .. } => holds_no_undefined(inner),
1311	        CollectedType::String
1312	        | CollectedType::Number
1313	        | CollectedType::Boolean
1314	        | CollectedType::Null
1315	        | CollectedType::Any
1316	        | CollectedType::Unknown
1317	        | CollectedType::Never
1318	        | CollectedType::BigInt
1319	        | CollectedType::Symbol
1320	        | CollectedType::StringLiteral(_)
1321	        | CollectedType::NumberLiteral(_)
1322	        | CollectedType::BoolLiteral(_)
1323	        | CollectedType::BigIntLiteral(_)
1324	        | CollectedType::UniqueSymbol
1325	        | CollectedType::Array(_)
1326	        | CollectedType::Tuple(_)
1327	        | CollectedType::Readonly(_)
1328	        | CollectedType::Object(_)
1329	        | CollectedType::Callable { .. }
1330	        | CollectedType::Function { .. }
1331	        | CollectedType::TemplateLiteral(_) => true,
1332	        _ => false,
1333	    }
1334	}
