cd /Users/gabe/Projects/caliper-fixtures/redteam-structural && python3 - <<'EOF'
import json, collections
st=json.load(open('stats.json')); f=json.load(open('findings.json'))
for k,v in st.items():
    if not k.startswith('special'): print(k, v)
tot=collections.Counter()
for k,v in st.items():
    for x in ('props','expanded','declined','wrong'): tot[x]+=v.get(x,0)
print(tot, [k for k,v in st.items() if v.get('error')])
c=collections.Counter((x['project'], x['file'].split('__')[0] if '__' in x['file'] else x['file']) for x in f)
for k,n in sorted(c.items()): print(n,k)
EOF

