import json, collections, re
R = '/Users/gabe/Projects/caliper-fixtures/redteam-structural/'
rows = []
for x in json.load(open(R + 'findings.json')):
    rows.append((x['project'], x['file'], x['expr'] or x['file']))
for fl in ('', '-eopt'):
    for x in json.load(open(R + f'findings2{fl}.json'))['findings']:
        rows.append(('r2' + fl, x['file'], x['expr']))
for line in open(R + 'r3.txt'):
    p = line.split(' | ')
    if len(p) > 2 and p[2] == 'WRONG':
        rows.append(('r3', p[0], p[1]))


def cls(project, f, e):
    if 'loose' in project:
        if f.startswith(('ident_opt_never', 'ident_opt_null', 'ident_opt_undef_only')):
            return 'R8 strictNullChecks off not read'
    if 'eopt' in project and f.startswith(('ident_opt_undef', 'ident_opt_obj_undef')):
        return 'R7 exactOptionalPropertyTypes not read'
    if f.startswith('comp_') or 'tlit_symbol' in f or project == 'r3' and 'dts' in f:
        return 'R1 type-literal computed key dropped'
    if 'getset_noann' in f:
        return 'R2 unannotated getter typed any'
    if f.startswith(('num_0', 'keys_str0', 'numkey')):
        return 'R3 key compared by spelling, not literal type'
    if f.startswith(('keys_enum_whole', 'enumkey')):
        return 'R4 enum key type read as its values'
    if 'class_iface' in f or f.startswith('merge_') and ('class' in f or 'abstract' in f):
        return 'R5 interface merged with class'
    if 'lib' in f or 'aug' in f or 'error' in f.lower():
        return 'R6 lib/global interface read from one declaration'
    if f.startswith('nn') and ('unknown' in e or 'void' in e):
        return 'R9 NonNullable<unknown|void> is T & {}'
    if f.startswith('nn_enum'):
        return 'R12 enum identity lost under NonNullable'
    if f.startswith('nn_shadowed'):
        return 'X checker suspect'
    if 'generic' in f or 'arrow' in f:
        return 'R10 type parameter does not shadow a module type'
    if 'alias_local_shadow' in f:
        return 'R11 alias index by bare name (function-local alias wins)'
    if 'import_partial' in f or 'import_star_partial' in f:
        return 'N nested named reference display (not a guard fault)'
    return 'UNCLASSIFIED'


c = collections.Counter(); ex = {}
for r in rows:
    k = cls(*r)
    c[k] += 1
    ex.setdefault(k, r)
for k, n in sorted(c.items()):
    print(n, k, '| e.g.', ex[k])
print(sum(c.values()))

